static int g_state = 0;  // 0 = not tried, 1 = ok, -1 = failed
static char g_info[512];
static void* g_handle = NULL;

static void fill_missing(void) {
    for (int i = 0; i < NPH_OCL_N; ++i) {
        if (!nph_ocl_tab[i] || nph_ocl_tab[i] == (void*)nph_ocl_missing) {
            nph_ocl_tab[i] = strcmp(k_names[i], "clCreateBufferWithProperties") == 0 ? (void*)nph_ocl_missing_cbwp
                                                                                  : (void*)nph_ocl_missing;
        }
    }
}

// Returns 1 when every required symbol resolved. `info` receives the library used or the reason.
__attribute__((visibility("hidden"))) int nph_ocl_shim_load(const char** info) {
    if (g_state == 0) {
        const char* cands[] = {getenv("NPH_OPENCL_LIB"), "libOpenCL.so", "/vendor/lib64/libOpenCL.so",
                               "/system/vendor/lib64/libOpenCL.so", "libOpenCL_adreno.so",
                               "/vendor/lib64/libOpenCL_adreno.so"};
        size_t off = 0;
        g_info[0]  = 0;
        for (size_t c = 0; c < sizeof(cands) / sizeof(cands[0]) && !g_handle; ++c) {
            if (!cands[c] || !cands[c][0]) continue;
            g_handle = dlopen(cands[c], RTLD_NOW | RTLD_LOCAL);
            if (g_handle) {
                snprintf(g_info, sizeof(g_info), "%s", cands[c]);
            } else if (off < sizeof(g_info) - 1) {
                const char* e = dlerror();
                off += (size_t)snprintf(g_info + off, sizeof(g_info) - off, "%s: %s; ", cands[c], e ? e : "?");
            }
        }
        if (!g_handle) {
            g_state = -1;
        } else {
            int missing = 0;
            for (int i = 0; i < NPH_OCL_N; ++i) {
                nph_ocl_tab[i] = dlsym(g_handle, k_names[i]);
                if (!nph_ocl_tab[i] && i < k_required) {
                    size_t l = strlen(g_info);
                    if (l < sizeof(g_info) - 1) snprintf(g_info + l, sizeof(g_info) - l, " falta %s", k_names[i]);
                    missing++;
                }
            }
            g_state = missing ? -1 : 1;
        }
        fill_missing();
    }
    if (info) *info = g_info;
    return g_state == 1;
}

